import pandas as pd


def _sig_part(x):
    """RTRIM(COALESCE(x, ''))"""
    if x is None:
        return ''
    try:
        if pd.isna(x):
            return ''
    except (TypeError, ValueError):
        pass
    s = str(x)
    return s.rstrip(' ')


def _sig(city, tier):
    return _sig_part(city) + '|' + _sig_part(tier)


def _get_input(inputs, name):
    """Lookup input dataframe by name, tolerating case differences."""
    if name in inputs:
        return inputs[name]
    lname = name.lower()
    for k, v in inputs.items():
        if k.lower() == lname:
            return v
    # Not found - raise informative error but still allow fallback to empty.
    raise KeyError(name)


def run(inputs: dict) -> dict:
    dim = _get_input(inputs, 'DIM_MEMBER').copy()
    stg = _get_input(inputs, 'STG_MEMBER').copy()

    # Ensure required columns exist even if empty frames are passed in.
    dim_cols = ['member_id', 'city', 'tier', 'eff_start_date', 'eff_end_date', 'is_current']
    for c in dim_cols:
        if c not in dim.columns:
            dim[c] = None

    stg_cols = ['member_id', 'city', 'tier', 'update_date']
    for c in stg_cols:
        if c not in stg.columns:
            stg[c] = None

    dim_out = dim.copy()

    new_rows = []

    for _, s in stg.iterrows():
        member_id = s['member_id']

        current_mask = (dim_out['member_id'] == member_id) & (dim_out['is_current'] == 1)
        current_rows = dim_out[current_mask]

        if current_rows.empty:
            # No current row -> plain insert, staged values kept exactly as-is.
            new_rows.append({
                'member_id': member_id,
                'city': s['city'],
                'tier': s['tier'],
                'eff_start_date': s['update_date'],
                'eff_end_date': None,
                'is_current': 1,
            })
        else:
            # At most one current row expected; take the first if more exist.
            c_idx = current_rows.index[0]
            c = dim_out.loc[c_idx]

            s_sig = _sig(s['city'], s['tier'])
            c_sig = _sig(c['city'], c['tier'])

            if s_sig != c_sig:
                # Close out the old current row.
                dim_out.loc[c_idx, 'eff_end_date'] = s['update_date']
                dim_out.loc[c_idx, 'is_current'] = 0

                # Insert new current row with staged values exactly as given.
                new_rows.append({
                    'member_id': member_id,
                    'city': s['city'],
                    'tier': s['tier'],
                    'eff_start_date': s['update_date'],
                    'eff_end_date': None,
                    'is_current': 1,
                })
            # else: signatures match -> no-op, dim row untouched.

    if new_rows:
        new_df = pd.DataFrame(new_rows, columns=dim_cols)
        dim_out = pd.concat([dim_out, new_df], ignore_index=True)

    dim_out = dim_out[dim_cols].reset_index(drop=True)

    return {'dim_member_out': dim_out}
